    this.flash = Math.max(0,this.flash-dt);
    this.bolts.forEach(b => b.age+=dt); this.bolts = this.bolts.filter(b=>b.age<.36);
    this.effects.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=50*dt;p.age+=dt;});this.effects=this.effects.filter(p=>p.age<p.life);
