    // Moon and distant hills.
    this.glow(w*.73,h*.21,h*.16,'#e1cff021');
    c.fillStyle='#d9cbe2';c.beginPath();c.arc(w*.73,h*.21,h*.047,0,TAU);c.fill();
    c.fillStyle='#202033';c.beginPath();c.moveTo(0,h*.49);for(let i=0;i<=12;i++)c.lineTo(i*w/12,h*(.35+Math.abs(Math.sin(i*1.9))*.13));c.lineTo(w,h);c.lineTo(0,h);c.fill();
    const floorY=this.project(0,0,34).y;
    const floor=c.createLinearGradient(0,floorY,0,h);floor.addColorStop(0,'#292538');floor.addColorStop(1,'#151523');c.fillStyle=floor;c.fillRect(0,floorY,w,h-floorY);
    for(let x=-14;x<=14;x+=2)this.line(this.project(x,0,2),this.project(x,0,38),'#b19ac315');
    for(let z=3;z<38;z+=2)this.line(this.project(-15,0,z),this.project(15,0,z),'#b19ac31a');
