    // Far arched portal.
    const gate=this.project(0,0,23),gs=gate.s;
    c.save();c.translate(gate.x,gate.y);c.strokeStyle='#8b71984a';c.lineWidth=gs*.13;c.beginPath();c.moveTo(-gs*1.7,0);c.lineTo(-gs*1.7,-gs*3.4);c.arc(0,-gs*3.4,gs*1.7,Math.PI,TAU);c.lineTo(gs*1.7,0);c.stroke();c.restore();
    this.floorSigil();
    // Magical braziers.
    for(const side of [-1,1]){
      const b=this.project(side*3,1.3,7);this.glow(b.x,b.y,90,'#bf8cdb29');
      const base=this.project(side*3,0,7);this.line(base,b,'#4b3c59',b.s*.22);
      this.poly([{x:b.x-b.s*.24,y:b.y},{x:b.x+b.s*.24,y:b.y},{x:b.x+b.s*.16,y:b.y+b.s*.22},{x:b.x-b.s*.16,y:b.y+b.s*.22}],'#79647f');
      for(let i=0;i<3;i++){const yy=b.y-14-(Math.sin(t*2.4+i)+1)*7;this.glow(b.x+Math.sin(t+i)*5,yy,35,'#b279e562');c.fillStyle='#e4c6ff';c.beginPath();c.ellipse(b.x+Math.sin(t+i)*5,yy,3,9,Math.sin(t)*.2,0,TAU);c.fill();}
    }
    if(intro){
      const p=this.project(1.5,2,7);this.crystal(p.x,p.y,p.s*.55,t,true);
      this.magicCircle(w*.72,h*.65,Math.min(w,h)*.15,t*.12,.55);
    }else{
      [...this.targets].sort((a,b)=>b.z-a.z).forEach(target=>{
        if(!target.alive)return;const p=this.project(target.x,target.y,target.z);
        this.crystal(p.x,p.y,p.s*target.r,t+target.phase,this.targetAt(aim)===target);
        const shadow=this.project(target.x,0,target.z);c.fillStyle='#08081380';c.beginPath();c.ellipse(shadow.x,shadow.y,p.s*.6,p.s*.14,0,0,TAU);c.fill();
      });
    }
    // Floating motes are low contrast so the aiming targets remain legible.
    for(let i=0;i<25;i++){const x=(Math.sin(i*34.2)*.5+.5)*w,y=((i/25+t*.009)%1)*h;this.glow(x,h-y,8,'#ceb1ee18');c.fillStyle='#d5b7ef55';c.fillRect(x,h-y,1.2,1.2);}
    this.hand(game?.charge || (intro?.35:0),intro);
    for(const bolt of this.bolts){
      const v=clamp(bolt.age/.25),bx=w*.68+(bolt.x-w*.68)*v,by=h*.88+(bolt.y-h*.88)*v;
      c.save();c.globalAlpha=1-bolt.age/.36;c.strokeStyle='#e2c9ff';c.shadowBlur=20;c.shadowColor='#ae75ec';c.lineWidth=3+bolt.power*4;c.beginPath();c.moveTo(bx,by);c.lineTo(bx+(bolt.x-bx)*.2,by+(bolt.y-by)*.2);c.stroke();this.glow(bx,by,24,'#dba8ffcc');c.restore();
    }
    for(const p of this.effects){c.globalAlpha=1-p.age/p.life;c.fillStyle='#e6c7ff';c.save();c.translate(p.x,p.y);c.rotate(p.age*3);c.fillRect(-p.size/2,-p.size/2,p.size,p.size);c.restore();}c.globalAlpha=1;
